'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { formatCurrency } from '@/lib/utils';
import { 
  AdjustmentsHorizontalIcon, 
  PlusIcon, 
  MagnifyingGlassIcon,
  ExclamationTriangleIcon,
  ArrowDownTrayIcon,
  ArrowUpTrayIcon
} from '@heroicons/react/24/outline';

// Mock inventory data
const mockInventory = [
  { 
    id: '1', 
    sku: 'WMP-001', 
    name: 'Wireless Mouse Pro', 
    category: 'Electronics',
    currentStock: 45,
    minStock: 10,
    maxStock: 100,
    unitCost: 15.99,
    unitPrice: 29.99,
    reorderPoint: 15,
    lastUpdated: '2024-03-12',
    supplier: 'Tech Supplies Inc'
  },
  { 
    id: '2', 
    sku: 'MKB-002', 
    name: 'Mechanical Keyboard', 
    category: 'Electronics',
    currentStock: 12,
    minStock: 5,
    maxStock: 50,
    unitCost: 45.99,
    unitPrice: 89.99,
    reorderPoint: 10,
    lastUpdated: '2024-03-11',
    supplier: 'Components Ltd'
  },
  { 
    id: '3', 
    sku: 'USB-003', 
    name: 'USB-C Cable', 
    category: 'Accessories',
    currentStock: 3,
    minStock: 20,
    maxStock: 200,
    unitCost: 4.99,
    unitPrice: 12.99,
    reorderPoint: 25,
    lastUpdated: '2024-03-10',
    supplier: 'Cable Co'
  },
];

const mockCategories = ['All', 'Electronics', 'Accessories', 'Office', 'Storage'];
const stockStatuses = ['All', 'In Stock', 'Low Stock', 'Out of Stock'];

export default function InventoryPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [stockStatus, setStockStatus] = useState('All');

  const getStockStatus = (item: any) => {
    if (item.currentStock === 0) return 'Out of Stock';
    if (item.currentStock <= item.minStock) return 'Low Stock';
    return 'In Stock';
  };

  const getStockStatusColor = (status: string) => {
    switch (status) {
      case 'In Stock': return 'status-success';
      case 'Low Stock': return 'status-warning';
      case 'Out of Stock': return 'status-error';
      default: return '';
    }
  };

  const filteredInventory = mockInventory.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                         item.sku.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || item.category === selectedCategory;
    const itemStatus = getStockStatus(item);
    const matchesStatus = stockStatus === 'All' || itemStatus === stockStatus;
    return matchesSearch && matchesCategory && matchesStatus;
  });

  const lowStockItems = mockInventory.filter(item => item.currentStock <= item.minStock);
  const outOfStockItems = mockInventory.filter(item => item.currentStock === 0);

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Inventory Header */}
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-primary">Inventory Management</h1>
              <p className="text-sm text-text-secondary">Track stock levels and manage inventory</p>
            </div>
            <div className="flex space-x-3">
              <button className="btn-secondary flex items-center space-x-2">
                <ArrowDownTrayIcon className="h-4 w-4" />
                <span>Import</span>
              </button>
              <button className="btn-secondary flex items-center space-x-2">
                <ArrowUpTrayIcon className="h-4 w-4" />
                <span>Export</span>
              </button>
              <button className="btn-primary flex items-center space-x-2">
                <PlusIcon className="h-4 w-4" />
                <span>Add Item</span>
              </button>
            </div>
          </div>

          {/* Inventory Stats */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-success/10 rounded-lg">
                  <AdjustmentsHorizontalIcon className="h-6 w-6 text-success" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Total Items</p>
                  <p className="text-2xl font-bold text-primary">{mockInventory.length}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-warning/10 rounded-lg">
                  <ExclamationTriangleIcon className="h-6 w-6 text-warning" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Low Stock</p>
                  <p className="text-2xl font-bold text-warning">{lowStockItems.length}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-error/10 rounded-lg">
                  <ExclamationTriangleIcon className="h-6 w-6 text-error" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Out of Stock</p>
                  <p className="text-2xl font-bold text-error">{outOfStockItems.length}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Search and Filters */}
          <div className="card p-4">
            <div className="flex flex-col lg:flex-row gap-4">
              <div className="flex-1">
                <div className="relative">
                  <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-text-secondary" />
                  <input
                    type="text"
                    placeholder="Search by name or SKU..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="input-field pl-10 w-full"
                  />
                </div>
              </div>
              <div className="flex gap-2">
                <select
                  value={selectedCategory}
                  onChange={(e) => setSelectedCategory(e.target.value)}
                  className="input-field"
                >
                  {mockCategories.map(category => (
                    <option key={category} value={category}>{category}</option>
                  ))}
                </select>
                <select
                  value={stockStatus}
                  onChange={(e) => setStockStatus(e.target.value)}
                  className="input-field"
                >
                  {stockStatuses.map(status => (
                    <option key={status} value={status}>{status}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          {/* Inventory Table */}
          <div className="card overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-surface border-b border-divider">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">SKU</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Product</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Category</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Current Stock</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Min/Max</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Unit Cost</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Unit Price</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Status</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-primary uppercase tracking-wider">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-divider">
                  {filteredInventory.map(item => {
                    const status = getStockStatus(item);
                    return (
                      <tr key={item.id} className="hover:bg-surface">
                        <td className="px-4 py-3 text-sm text-primary font-medium">{item.sku}</td>
                        <td className="px-4 py-3 text-sm text-primary">{item.name}</td>
                        <td className="px-4 py-3 text-sm text-text-secondary">{item.category}</td>
                        <td className="px-4 py-3 text-sm">
                          <span className={`font-medium ${getStockStatusColor(status)}`}>
                            {item.currentStock}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-sm text-text-secondary">
                          {item.minStock}/{item.maxStock}
                        </td>
                        <td className="px-4 py-3 text-sm text-primary">{formatCurrency(item.unitCost)}</td>
                        <td className="px-4 py-3 text-sm text-primary">{formatCurrency(item.unitPrice)}</td>
                        <td className="px-4 py-3 text-sm">
                          <span className={`px-2 py-1 text-xs rounded-full ${getStockStatusColor(status)}`}>
                            {status}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-sm">
                          <div className="flex space-x-2">
                            <button className="text-info hover:text-info/80">
                              <AdjustmentsHorizontalIcon className="h-4 w-4" />
                            </button>
                            <button className="text-warning hover:text-warning/80">
                              <PlusIcon className="h-4 w-4" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
